{
  "spells": [
    {
      "id": "spell_light_13",
      "theory": "昼辉束把魔力压缩在指间或法器的棱面内，再沿一条细窄轴线释放，形成灼目的光束。它依赖可见的折射面来定向，因此水晶、打磨过的金属片或刻槽的骨片都能成为媒介。光束只沿直线前进，遇到不透明物便停住，不具备穿透石墙或点燃远处易燃物的能力。对拥有视觉的目标，强光会迫使瞳孔收缩、短暂遮蔽视线，但不会造成失明或持续灼伤。",
      "casting": "将棱面举至视线高度，另一手食中二指并拢，沿棱面边缘快速划出直线，同时把魔力压入棱心。出手瞬间屏住呼吸，避免光束随胸腔起伏而摇晃。",
      "failure": "魔力在棱面内打旋，光束散成一片模糊的白斑，只照亮近处却无法定向。棱面若受热不均可能发出脆响并裂开细纹，使下一次施放需要更换媒介。",
      "counters": [
        "迅速举盾或转身背对，用不透明面阻断视线接触。",
        "向棱面泼洒冷水或湿泥，使折射面污浊而光束散乱。",
        "在光束路径上拉起烟幕，让光被颗粒散射成无害的亮雾。"
      ],
      "socialConsequences": "在河谷乡约见证的集市上，商队护卫愿意租用昼辉束来警告靠近的野兽，但不会用它直照路人。城市公会要求施术前确认周围没有正在搬运易碎品的工人，以免眩光引发摔损。港口装卸区若有人用光束扫射他人眼睛，会被港务视为扰乱作业并追究货损责任。卖灯油和火把的摊贩担忧夜间照明被替代，却仍欢迎它用于地窖查货。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时光束边缘毛糙，有效距离常缩到二十步内。",
        "熟练后光束收束更直，四十步内能稳定照中目标。",
        "精熟者能控制照亮时长，减少对旁观者眼睛的干扰。",
        "更高熟练度让棱面耐久提高，连续施放不易开裂。"
      ]
    },
    {
      "id": "spell_light_14",
      "theory": "显形环把魔力铺成一层极薄的环带，沿地面或墙面缓慢扩散，专门捕捉依赖光学伪装隐藏的轮廓。它作用于折射率被改变的区域，使那些靠弯曲光线藏身的形体边缘泛起微光。环带不能进入封闭容器，也无法破除直接作用于心智的幻象。对以阴影、斗篷或变色皮肤隐藏的目标，环带经过时会勾勒出模糊的边界，但不揭示其身份或意图。",
      "casting": "将魔力聚于掌心，以脚跟为轴缓慢转身一周，同时让环带贴地推出。掌心保持朝下，若中途抬高，环带会跳起并断裂成弧段。",
      "failure": "环带推出时厚薄不均，只在地面留下几段断续的亮弧，无法合拢。若施术者转身过快，环带会卷回脚边，把施术者自己的轮廓照得发亮，却漏掉真正隐藏的目标。",
      "counters": [
        "用厚重毯子或木板完全遮住地面，阻断环带扩散路径。",
        "在环带抵达前踏入流水中，让流动水面打散魔力薄层。",
        "以强风扬起沙尘，使环带被颗粒摩擦消耗而提前消散。"
      ],
      "socialConsequences": "河谷乡约允许在夜间巡逻时公开使用显形环，但若环带照到借宿商队的货堆，须先取得货主同意。中陆城市的公会视其为查缉盗匪的合规手段，不过对平民密集的市集要求提前申请许可，以免惊扰人群。琥珀海岸港务规定，在货舱通道施放前必须通知管货员，否则因环带导致搬运工慌乱摔坏货物要赔偿。靠伪装混入码头的走私者最恨此术，而正当商贩则欢迎它吓退扒手。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学环带扩散缓慢，常需两息才能覆盖周身十步。",
        "熟练后环带边缘均匀，四十步内可稳定合拢成圈。",
        "精熟者能控制环带亮度，减少对夜行者的惊扰。",
        "更高熟练度让环带绕过浅水，仍无法穿透厚墙。"
      ]
    }
  ]
}
